import { useState, FormEvent } from 'react';
import {
  JxForm,
  JxFormField,
  JxLabel,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <JxForm
      className="jx-stack jx-gap-md"
      style={{ maxWidth: 'var(--jx-size-form-md)' }}
      onSubmit={handleSubmit}
    >
      <JxFormField>
        <JxLabel htmlFor="profile-name">Имя</JxLabel>
        <JxInput
          id="profile-name"
          name="name"
          value={name}
          placeholder="Введите имя"
          onChange={(event) => setName(event.target.value)}
        />
      </JxFormField>

      <JxFormField>
        <JxLabel htmlFor="profile-language">Язык интерфейса</JxLabel>
        <JxSelect
          id="profile-language"
          name="language"
          value={language}
          onValueChange={(value) => setLanguage(value as Language)}
        >
          <JxSelectOption value="ru">Русский</JxSelectOption>
          <JxSelectOption value="en">Английский</JxSelectOption>
        </JxSelect>
      </JxFormField>

      <JxFormField className="jx-row jx-items-center jx-justify-between">
        <JxLabel htmlFor="profile-email-notifications">Уведомления на почту</JxLabel>
        <JxSwitch
          id="profile-email-notifications"
          name="emailNotifications"
          checked={emailNotifications}
          onCheckedChange={setEmailNotifications}
        />
      </JxFormField>

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </JxForm>
  );
}

